/* Final retest corrections: tablet header/event readability and mobile party labels. */
@media (max-width: 1000px) {
  .header-inner {
    position: relative;
    grid-template-columns: minmax(0, 1fr) auto;
  }
  .header-tools {
    display: contents;
  }
  .header-tools .menu-button {
    display: inline-grid;
    grid-column: 2;
    grid-row: 1;
  }
  .header-tools .header-search {
    grid-column: 1 / -1;
    grid-row: 2;
    width: 100%;
  }
  .header-tools .header-search input {
    width: auto;
    flex: 1;
  }
  .primary-nav {
    position: absolute;
    z-index: 10;
    top: calc(100% + 1px);
    right: 0;
    left: 0;
    display: none;
    padding: 8px;
    background: var(--navy);
    border: 1px solid rgba(255, 255, 255, 0.15);
    box-shadow: var(--shadow);
  }
  .primary-nav.is-open {
    display: block;
  }
  .primary-nav ul {
    display: grid;
  }
  .primary-nav a {
    width: 100%;
    justify-content: flex-start;
  }
  .home-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 480px) {
  .party-slots {
    grid-template-columns: 1fr;
  }
  .party-slot.is-filled strong,
  .party-slot.is-filled span {
    overflow: visible;
    text-overflow: clip;
    white-space: normal;
  }
}
